package com.jizza.engine.api.chat;

import com.fasterxml.jackson.databind.JsonNode;
import java.util.UUID;

/**
 * A message the user sent. {@code conversationId} null starts a new conversation.
 * {@code clientMessageId} is generated by the client once per message, so a retried send returns
 * the turn already running instead of starting a second one. {@code context} describes what is
 * open on {@code screen} (the workflow Builder, one step's settings) for this turn only; it is never
 * stored.
 */
public record TurnSubmission(UUID conversationId, UUID clientMessageId, String text, String screen,
                             boolean incognito, JsonNode context) {

  public TurnSubmission(UUID conversationId, UUID clientMessageId, String text, String screen,
                        boolean incognito) {
    this(conversationId, clientMessageId, text, screen, incognito, null);
  }
}
